@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --color-bg-base: #0a0f1e;
  --color-bg-surface: #111827;
  --color-bg-elevated: #1e2a3a;
  --color-bg-overlay: #243247;
  --color-border-subtle: #1e293b;
  --color-border-default: #2d3f52;
  --color-border-strong: #3d5168;
  --color-text-primary: #f1f5f9;
  --color-text-secondary: #94a3b8;
  --color-text-tertiary: #64748b;
  --color-accent: #38bdf8;
  --color-accent-muted: #1e3a4f;
  --color-accent-hover: #7dd3fc;
  --color-success: #34d399;
  --color-warning: #fbbf24;
  --color-error: #f87171;
}

.theme-light {
  --color-bg-base: #f8fafc;
  --color-bg-surface: #ffffff;
  --color-bg-elevated: #f1f5f9;
  --color-bg-overlay: #e2e8f0;
  --color-border-subtle: #e2e8f0;
  --color-border-default: #cbd5e1;
  --color-border-strong: #94a3b8;
  --color-text-primary: #0f172a;
  --color-text-secondary: #475569;
  --color-text-tertiary: #94a3b8;
  --color-accent: #0284c7;
  --color-accent-muted: #e0f2fe;
  --color-accent-hover: #0369a1;
  --color-success: #059669;
  --color-warning: #d97706;
  --color-error: #dc2626;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body, #root {
  height: 100%;
  font-family: 'Inter', 'PingFang SC', 'Microsoft YaHei', system-ui, sans-serif;
  background: var(--color-bg-base);
  color: var(--color-text-primary);
  overflow: hidden;
}

::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--color-border-default);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--color-border-strong);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

.animate-stagger > *:nth-child(1) { animation-delay: 0ms; }
.animate-stagger > *:nth-child(2) { animation-delay: 60ms; }
.animate-stagger > *:nth-child(3) { animation-delay: 120ms; }
.animate-stagger > *:nth-child(4) { animation-delay: 180ms; }
.animate-stagger > *:nth-child(5) { animation-delay: 240ms; }
.animate-stagger > *:nth-child(6) { animation-delay: 300ms; }

.streaming-char {
  display: inline-block;
  opacity: 0;
  transform: translateY(4px);
  animation: streamChar 0.15s ease-out forwards;
}

@keyframes streamChar {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

